// MsgServer is the server API for Msg service.
type MsgServer interface {
	// UpdateParams sets the settings and appoints the office. Governance only;
	// the office must be a group account.
	UpdateParams(context.Context, *MsgUpdateParams) (*MsgUpdateParamsResponse, error)
	// AdmitJeweler admits a business and opens its collection. Office only.
	AdmitJeweler(context.Context, *MsgAdmitJeweler) (*MsgAdmitJewelerResponse, error)
	// SuspendJeweler stops a jeweler acting: no registration, no sale of its stock, and its staff's offers die. Office only.
	SuspendJeweler(context.Context, *MsgSuspendJeweler) (*MsgSuspendJewelerResponse, error)
	// ReinstateJeweler lets a suspended jeweler act again. Office only.
	ReinstateJeweler(context.Context, *MsgReinstateJeweler) (*MsgReinstateJewelerResponse, error)
	// SetStaff adds and removes the people who act for a jeweler.
	SetStaff(context.Context, *MsgSetStaff) (*MsgSetStaffResponse, error)
	// RegisterJewel mints a jewel into its jeweler's stock.
	RegisterJewel(context.Context, *MsgRegisterJewel) (*MsgRegisterJewelResponse, error)
	// AmendJewel appends a correction to a jewel's record.
	AmendJewel(context.Context, *MsgAmendJewel) (*MsgAmendJewelResponse, error)
	// OfferJewel opens an offer to an account or a claim key.
	OfferJewel(context.Context, *MsgOfferJewel) (*MsgOfferJewelResponse, error)
	// CancelOffer closes an open offer.
	CancelOffer(context.Context, *MsgCancelOffer) (*MsgCancelOfferResponse, error)
	// AcceptOffer takes a jewel offered to the signer's account.
	AcceptOffer(context.Context, *MsgAcceptOffer) (*MsgAcceptOfferResponse, error)
	// ClaimOffer takes a jewel offered to a claim key.
	ClaimOffer(context.Context, *MsgClaimOffer) (*MsgClaimOfferResponse, error)
	// ReportStolen flags a jewel and closes its offer.
	ReportStolen(context.Context, *MsgReportStolen) (*MsgReportStolenResponse, error)
	// ClearStolen lifts the flag.
	ClearStolen(context.Context, *MsgClearStolen) (*MsgClearStolenResponse, error)
	// AttachBenefit adds a benefit to a jewel.
	AttachBenefit(context.Context, *MsgAttachBenefit) (*MsgAttachBenefitResponse, error)
	// RedeemBenefit records one use, with the owner's signed voucher.
	RedeemBenefit(context.Context, *MsgRedeemBenefit) (*MsgRedeemBenefitResponse, error)
	// ProposeReassignment opens the public window. Office only.
	ProposeReassignment(context.Context, *MsgProposeReassignment) (*MsgProposeReassignmentResponse, error)
	// VetoReassignment closes it. The current owner only.
	VetoReassignment(context.Context, *MsgVetoReassignment) (*MsgVetoReassignmentResponse, error)
	// CompleteReassignment moves the jewel once the window has passed. Anyone.
	CompleteReassignment(context.Context, *MsgCompleteReassignment) (*MsgCompleteReassignmentResponse, error)
}

